 */
@Getter
@Setter
@ToString
public class PolicySearchResultVO {

    /** 증권번호 */
    private String policyNo;

    /** 상품명 */
    private String productName;

    /** 상품코드 */
    private String productCode;

    /** 고객명 */
    private String customerName;

    /** 고객 주민등록번호 (마스킹 처리: 앞 6자리 + ******* 형태) */
    private String customerRrnMasked;

log.info("[PSI] 증권조회 결과 건수: {}", totalCount);

        // 화면에 전달할 데이터 설정
        model.addAttribute("searchVO", searchVO);
        model.addAttribute("resultList", resultList);
        model.addAttribute("totalCount", totalCount);
        model.addAttribute("searchExecuted", true);

        return "policySearch";
    }

log.info("[DSI] 증권목록 조회 완료 - 조회 건수: {}", resultList.size());
        return resultList;
    }

    /**
     * 증권 단건 상세 조회
     */
    @Override
    public PolicySearchResultVO selectPolicyDetail(String policyNo) {
        log.info("[DSI] 증권상세 조회 - 증권번호: {}", policyNo);

        PolicySearchResultVO result = policySearchMapper.selectPolicyDetail(policyNo);

        if (result != null) {
            applyPrivacyMasking(result);
        }

        return result;
    }

/**
 * 한화AX 증권조회 데모 애플리케이션
 *
 * 계층 구조:
 *   화면 (Thymeleaf HTML)
 *     ↓
 *   PSI - Presentation Service Interface (Controller)
 *     ↓
 *   DSI - Data Service Interface (Service)
 *     ↓
 *   MyBatis Mapper (SQL)
 *     ↓
 *   DB (H2 In-Memory)
 */
@SpringBootApplication
@MapperScan("com.hanwha.ax.mapper")
public class PolicySearchApplication {

    public static void main(String[] args) {
        SpringApplication.run(PolicySearchApplication.class, args);
    }
}

/** DSI - Data Service Interface (업무 서비스 계층) */
    private final PolicySearchDSI policySearchDSI;

    /**
     * 증권조회 화면 진입
     * GET /policy/search
     */
    @GetMapping("/search")
    public String policySearchView(Model model) {
        log.info("[PSI] 증권조회 화면 진입");
        // 빈 검색조건 VO를 모델에 담아 화면으로 전달
        model.addAttribute("searchVO", new PolicySearchVO());
        return "policySearch";  // resources/templates/policySearch.html
    }
